export const TRICK_KEY = "periwinkle";
export const TRICKS = ["spiralcrawl", "filmgraze", "opercshut", "tidehuddle", "tipup", "littorine", "littorinahush"] as const;
export const HAPPY = ["densspire", "inkspire", "denslittorina"] as const;
export type PeriwinkleTrickKind = (typeof TRICKS)[number];
export type PeriwinkleHappyKind = (typeof HAPPY)[number];
export type TrickAnim = "idle" | "walk" | "sit" | "sleep" | "talk" | "play";
export type TrickPhase = "go" | "hold" | "release" | "done";
export type HappyPhase = "go" | "done";

export type TrickFlags = {
  asleep?: boolean;
  hidden?: boolean;
  leaving?: boolean;
  cmd?: string;
  windowPlay?: boolean;
  card?: boolean;
};

export type PeriwinkleTrick = {
  kind: PeriwinkleTrickKind;
  phase: TrickPhase;
  t: number;
  x: number;
  lift: number;
  rot: number;
  anim: TrickAnim;
  facing: 1 | -1;
  fromX: number;
  abort?: boolean;
};

export type PeriwinkleHappy = {
  kind: PeriwinkleHappyKind;
  happy: true;
  phase: HappyPhase;
  t: number;
  x: number;
  lift: number;
  rot: number;
  anim: TrickAnim;
  facing: 1 | -1;
  fromX: number;
  abort?: boolean;
};

export const HAPPY_DUR = { densspire: 1.70, inkspire: 1.84, denslittorina: 1.76 } as const;
export const LITTORINAHUSH_HOLD = 11.2;
export const RELEASE_S = 1.18;
export const DUR = {
  littorinahush: LITTORINAHUSH_HOLD + RELEASE_S,
  spiralcrawl: 2.48,
  filmgraze: 2.42,
  opercshut: 2.40,
  tidehuddle: 2.44,
  tipup: 2.38,
  littorine: 2.56,
} as const;

export function canStart(state: TrickFlags | undefined) {
  if (!state) return false;
  if (state.asleep || state.hidden || state.leaving || state.windowPlay || state.card) return false;
  const cmd = String(state.cmd || "");
  if (cmd === "sleep" || cmd === "leave" || cmd === "hide" || cmd === "rest") return false;
  if (cmd === "seek" || cmd === "eat" || cmd === "play" || cmd === "talk" || cmd === "enter") return false;
  return true;
}

export function shouldAbort(state: TrickFlags | undefined) {
  if (!state) return true;
  if (state.asleep || state.hidden || state.leaving || state.windowPlay || state.card) return true;
  const cmd = String(state.cmd || "");
  return (
    cmd === "sleep" ||
    cmd === "leave" ||
    cmd === "hide" ||
    cmd === "rest" ||
    cmd === "seek" ||
    cmd === "eat" ||
    cmd === "play" ||
    cmd === "talk" ||
    cmd === "enter"
  );
}

export function nextTrickWait(justFinished: boolean, rand?: number, kind?: PeriwinkleTrickKind | string) {
  const roll = rand == null ? Math.random() : rand;
  if (kind === "littorinahush") return 40 + roll * 26;
  if (kind === "tipup" || kind === "spiralcrawl" || kind === "tidehuddle") return 12.8 + roll * 9.4;
  if (kind === "opercshut" || kind === "filmgraze" || kind === "littorine") return 11.6 + roll * 8.5;
  return justFinished ? 8.5 + roll * 8.4 : 4.4 + roll * 7.4;
}

